/* 平缝机控制器 CTRL-LS 示例固件（第 159 轮 159f）。
 * 时间基准是 16 kHz 电流环中断（motor.c）；它每 1 ms 调一次缝纫状态机（sew.c 的 motor_ms_hook）。主循环只等中断。
 * 开机：量电流零点 → d 轴通电对零 → 低速转找编码器 Z 相（针杆最高点 = 主轴 0°）→ 停上针位 → 就绪。
 * 板上的调试口只有 SWD：遥测区 mc（电机）、sw（缝纫）、设置 cfg 给调试器看、改（仿真里由 Renode 读写内存）。
 * 没做的（留接口）：针距步进电机（TIM3 → PB4 / PB5）、操作面板串口（USART2 → PA2 / PA3）、联网、校正关断（PB9）。
 * 示例固件，仿真验证；电机未选型，参数见 README；不能直接用于产品。 */
#include <stdint.h>
#include "clock.h"
#include "motor.h"
#include "regs.h"
#include "sew.h"

int main(void)
{
    clock_init();
    sew_init();                 /* 电磁铁引脚先置成“不吸合” */
    motor_init();
    for (volatile uint32_t i = 0; i < 170000u; i++) {   /* 约 5 ms：电流零点（中断里量 64 个周期，4 ms） */
    }
    motor_start();
    for (;;) {
        __asm volatile("wfi");
    }
}

/* 缝纫状态机（第 159 轮 159f），1 kHz（电流环中断里经 motor_ms_hook 调）。
 * 脚踏板：霍尔 0.5–4.5 V（设计描述 sensor_inputs.pedal_v_max），经 10 k / 20 k 分压进 PB1；motor.c 换回霍尔电压。
 *   后踩 < 0.9 V、回中 0.9–1.4 V、前踩 > 1.4 V；前踩 1.4 → 4.2 V 对应 200 → 5000 r/min（分界和满量程是示例值，按脚踏板标定改）。
 * 电磁铁（按原理图 U10）：剪线 PA5、拨线 PA11、倒缝 PA12、抬压脚 PA15。经 2N7002 反相驱动 80 V 管：
 *   引脚低 = 吸合；复位时引脚上拉、电磁铁不动作——所以先把输出置高、再把引脚设成输出。 */
#include "sew.h"
#include "motor.h"
#include "regs.h"

volatile cfg_t cfg = {
    0x31474643u,      /* "CFG1" */
    4, 4, 1800.0f,    /* 起缝加固：正 4 针、倒 4 针、1800 r/min（示例） */
    300.0f,           /* 剪线转速（159c） */
    7000, 18000,      /* 上针位 70°、下针位 180° */
    20000, 33000,     /* 剪线窗口 200°–330° */
    50,               /* 拨线 50 ms（示例） */
    10000,            /* 抬压脚最长 10 s（示例） */
};
volatile sew_t sw;

#define SOL_TRIM 0
#define SOL_WIPE 1
#define SOL_REV 2
#define SOL_FOOT 3
static const uint32_t SOL_PIN[4] = {5, 11, 12, 15};

static uint32_t trim_phase, trim_win, trim_prev_out;
static int32_t trim_start;

static void sol(int k, int on)
{
    if (on) {
        GPIO_BSRR(GPIOA_BASE) = 1u << (SOL_PIN[k] + 16);                          /* 拉低 = 吸合 */
        sw.sol |= 1u << k;
    } else {
        GPIO_BSRR(GPIOA_BASE) = 1u << SOL_PIN[k];
        sw.sol &= ~(1u << k);
    }
}

void sew_init(void)
{
    sw.magic = 0x31574553u;                                                       /* "SEW1" */
    RCC_AHB2ENR |= RCC_GPIOAEN;
    for (int k = 0; k < 4; k++) {
        GPIO_BSRR(GPIOA_BASE) = 1u << SOL_PIN[k];                                 /* 先置高（不吸合） */
        GPIO_MODER(GPIOA_BASE) = (GPIO_MODER(GPIOA_BASE) & ~(3u << (2 * SOL_PIN[k]))) | (1u << (2 * SOL_PIN[k]));
    }
    sw.sol = 0;
    sw.state = SW_BOOT;
}

static void go(uint32_t s)
{
    sw.state = s;
    sw.t_state_ms = mc.ms;
}

static void all_off(void)
{
    for (int k = 0; k < 4; k++) {
        sol(k, 0);
    }
}

void motor_z_hook(void)
{
    sw.stitches++;
    sw.seam_stitches++;
}

static int in_win(int32_t a) { return a >= cfg.trim_on_x100 && a < cfg.trim_off_x100; }

void motor_ms_hook(void)
{
    /* 脚踏 */
    float v = mc.pedal_v;
    sw.pedal = v < 0.9f ? 0u : (v < 1.4f ? 1u : 2u);
    float r = 200.0f + (v - 1.4f) / (4.2f - 1.4f) * (RPM_MAX - 200.0f);
    sw.pedal_rpm = r < 200.0f ? 200.0f : (r > RPM_MAX ? RPM_MAX : r);

    if (mc.state == MS_FAULT && sw.state != SW_FAULT) {
        all_off();                                                                /* 故障：电磁铁全部释放 */
        go(SW_FAULT);
    }
    uint32_t dt = mc.ms - sw.t_state_ms;
    switch (sw.state) {
    case SW_BOOT:
        if (mc.state == MS_READY) {
            go(SW_IDLE);
        }
        break;
    case SW_IDLE:
        if (sw.pedal == 2) {
            sw.seam_stitches = 0;
            if (cfg.bt_fwd + cfg.bt_rev > 0) {
                motor_speed(cfg.bt_rpm);
                go(SW_BT_FWD);
            } else {
                motor_speed(sw.pedal_rpm);
                go(SW_SEW);
            }
        } else if (sw.pedal == 0) {
            sol(SOL_FOOT, 1);
            go(SW_FOOT);
        }
        break;
    case SW_BT_FWD:                                                               /* 加固走完才看脚踏（中途松脚也缝完） */
        if (sw.seam_stitches >= cfg.bt_fwd) {
            sol(SOL_REV, 1);
            go(SW_BT_REV);
        }
        break;
    case SW_BT_REV:
        if (sw.seam_stitches >= cfg.bt_fwd + cfg.bt_rev) {
            sol(SOL_REV, 0);
            go(SW_SEW);
        }
        break;
    case SW_SEW:
        if (sw.pedal == 2) {
            motor_speed(sw.pedal_rpm);
        } else if (sw.pedal == 1) {
            motor_speed(cfg.trim_rpm);
            go(SW_STOP_DN);
        } else {
            trim_phase = 0;
            motor_speed(cfg.trim_rpm);
            go(SW_TRIM);
        }
        break;
    case SW_STOP_DN:
        if (sw.pedal == 2) {
            go(SW_SEW);
        } else if (sw.pedal == 0) {
            trim_phase = 0;
            motor_speed(cfg.trim_rpm);
            go(SW_TRIM);
        } else if (mc.mode == MM_SPEED && mc.speed_ref <= cfg.trim_rpm) {
            motor_stop_at(cfg.down_x100);
        } else if (motor_stopped()) {
            go(SW_DOWN);
        }
        break;
    case SW_DOWN:
        if (sw.pedal == 2) {
            motor_speed(sw.pedal_rpm);
            go(SW_SEW);
        } else if (sw.pedal == 0) {
            trim_phase = 0;
            motor_speed(cfg.trim_rpm);
            go(SW_TRIM);
        }
        break;
    case SW_TRIM:
        /* 0：减（或加）到剪线转速；1：在剪线转速下至少转一整圈、并且剪完（剪线电磁铁在窗口里吸合、释放过一次）；2：停上针位 */
        if (trim_phase == 0 && motor_ramp_done()) {
            trim_phase = 1;
            trim_win = 0;
            trim_prev_out = 0;
            trim_start = mc.pos_cnt;
        } else if (trim_phase == 1 && mc.pos_cnt - trim_start >= CNT_PER_REV && trim_win == 2) {
            trim_phase = 2;
            motor_stop_at(cfg.up_x100);
        }
        if (trim_phase >= 1 && trim_win < 2) {
            /* 从窗口外转进来（过 200°）才吸合：剪线转速到了的时候主轴若已在窗口里，等下一圈，不半路吸合 */
            int w = in_win(mc.angle_x100);
            if (w && trim_win == 0 && trim_prev_out) {
                sol(SOL_TRIM, 1);
                trim_win = 1;
            } else if (!w && trim_win == 0) {
                trim_prev_out = 1;
            } else if (!w && trim_win == 1) {
                sol(SOL_TRIM, 0);
                trim_win = 2;
                sw.trims++;
            }
        }
        if (trim_phase == 2 && motor_stopped()) {
            sol(SOL_TRIM, 0);
            sol(SOL_WIPE, 1);
            go(SW_WIPE);
        }
        break;
    case SW_WIPE:
        if (dt >= cfg.wipe_ms) {
            sol(SOL_WIPE, 0);
            sol(SOL_FOOT, 1);
            go(SW_FOOT);
        }
        break;
    case SW_FOOT:
        if (sw.pedal != 0 || dt >= cfg.foot_max_ms) {                             /* 松开后踩（或到时间）：压脚放下，等下一条缝 */
            sol(SOL_FOOT, 0);
            go(SW_IDLE);
        }
        break;
    default:
        break;
    }
}

/* 缝纫状态机（第 159 轮 159f）：脚踏 → 起缝加固 → 缝纫 → 停针 → 剪线 → 拨线 → 抬压脚。 */
#ifndef SEW_H
#define SEW_H
#include <stdint.h>

enum {
    SW_BOOT = 0,      /* 等电机就绪（对零、找 Z 相、停上针位） */
    SW_IDLE = 1,      /* 一条缝开始前：停在上针位、压脚放下 */
    SW_BT_FWD = 2,    /* 起缝加固：先正缝 bt_fwd 针 */
    SW_BT_REV = 3,    /* 起缝加固：再倒缝 bt_rev 针（倒缝电磁铁吸合） */
    SW_SEW = 4,       /* 缝纫：转速跟脚踏 */
    SW_STOP_DN = 5,   /* 脚踏回中：减速、停下针位 */
    SW_DOWN = 6,      /* 停在下针位（针在布里），可接着缝或剪线 */
    SW_TRIM = 7,      /* 脚踏后踩：减到剪线转速、转一针剪线（剪线电磁铁在剪线角度窗口内吸合）、停上针位 */
    SW_WIPE = 8,      /* 拨线电磁铁吸合一下 */
    SW_FOOT = 9,      /* 抬压脚（后踩不松就一直抬着） */
    SW_FAULT = 10
};

/* 操作面板能改的设置（示例默认值；仿真里由 Renode 写内存，相当于面板改设置） */
typedef struct {
    uint32_t magic;           /* "CFG1" */
    uint32_t bt_fwd;          /* 起缝加固正缝针数（0 = 不加固） */
    uint32_t bt_rev;          /* 起缝加固倒缝针数 */
    float bt_rpm;             /* 起缝加固转速 r/min */
    float trim_rpm;           /* 剪线转速 r/min（159c：300） */
    int32_t up_x100;          /* 上针位 0.01°（第 138 轮：70°） */
    int32_t down_x100;        /* 下针位 0.01°（针杆最低点 180°，第 138 轮 G2 机构） */
    int32_t trim_on_x100;     /* 剪线电磁铁吸合角度窗口 200°–330°（159c / 第 138 轮剪线动刀） */
    int32_t trim_off_x100;
    uint32_t wipe_ms;         /* 拨线电磁铁吸合时间 */
    uint32_t foot_max_ms;     /* 抬压脚最长时间（线圈 3 A 不能一直通电；示例） */
} cfg_t;

typedef struct {
    uint32_t magic;           /* "SEW1" */
    uint32_t state;           /* SW_* */
    uint32_t stitches;        /* 开机以来的针数（过针杆最高点计一针） */
    uint32_t seam_stitches;   /* 这条缝的针数 */
    uint32_t sol;             /* 电磁铁：位 0 剪线、1 拨线、2 倒缝、3 抬压脚（1 = 吸合） */
    uint32_t pedal;           /* 0 后踩、1 回中、2 前踩 */
    float pedal_rpm;          /* 脚踏给的转速 */
    uint32_t trims;           /* 剪线次数 */
    uint32_t t_state_ms;      /* 进当前状态时的时刻 */
} sew_t;

extern volatile cfg_t cfg;
extern volatile sew_t sw;

void sew_init(void);

#endif

/* 主轴电机控制（第 159 轮 159f）。一次 ADC 注入组转换完成中断 = 一个 16 kHz 电流环周期：
 *   读三相电流、母线、脚踏 → 过流保护 → 读编码器（TIM4）、看 Z 相（PA6）→ 电角度 → Clarke / Park → d、q 两个 PI → 反 Park → SVPWM
 *   每 8 次（2 kHz）速度环，每 16 次（1 kHz）位置环、爬坡、保护、缝纫状态机节拍。
 * 磁场定向控制的写法沿用驱动板 B 版 motor.c（第 102 轮）；速度环、停针的参数取 159c 的主轴伺服复算（第 138 轮 gc_sim.py 的模型）：
 *   速度环带宽 40 Hz（Kp = J·ωs / Kt，积分时间 4 / ωs）、按给定的加速度加前馈 J·a、不加负载前馈；
 *   停针：位置环 Kp = ωs / 4，限速 300 r/min，目标是前面最近的那个转角。
 * 引脚（按原理图 U10）：TIM1 CH1–3 = PA8–PA10、CH1N–3N = PB13–PB15（AF6）；PB12 = IPM_SD（高 = 工作，拉低关断功率模块）；
 *   U / V / W 相电流 PA1 / PA7 / PB0 → 片内运放 OPAMP1 / 2 / 3（PGA 8 倍）→ ADC1_IN13 / ADC2_IN16 / ADC2_IN18；
 *   母线 PA0 = ADC1_IN1（3 MΩ / 22 kΩ）；脚踏 PB1 = ADC1_IN12（10 k / 20 k）；编码器 A / B = PB6 / PB7（TIM4 编码器模式，AF2）、Z = PA6。
 * 编码器信号经 SN74LVC14 反相：A、B 同时反相不改变计数方向；Z 相在主控引脚上是低电平有效。
 * 电流换算（设计描述 low_side_sense）：V_运放 = 8 × (V_采样 · 15/16 + 3.3/16)，下桥采样 V_采样 = −i × 25 mΩ（电流流向电机为正）
 *   → V = 1.65 − 0.1875 × i；零点开机时实测。 */
#include "motor.h"
#include "regs.h"

volatile mc_t mc;

#define TS (1.0f / PWM_HZ)
#define PI_F 3.14159265f
#define TWO_PI 6.28318531f
#define A_PER_CODE (3.3f / 4095.0f / 0.1875f)
#define V_PER_CODE (3.3f / 4095.0f * (3022.0f / 22.0f))
#define PEDAL_PER_CODE (3.3f / 4095.0f * 1.5f)

/* 电流环：带宽 1 kHz，Kp = L·ωc，Ki = R·ωc（零极点对消，同 B 版） */
#define KP_I (L_PHASE * TWO_PI * 1000.0f)
#define KI_I (R_PHASE * TWO_PI * 1000.0f)
/* 速度环：带宽 40 Hz（159c 推荐值），Kp = J·ωs / Kt，Ki = Kp·ωs / 4 */
#define WS (TWO_PI * 40.0f)
#define KP_W (J_TOTAL * WS / KT)
#define KI_W (KP_W * WS / 4.0f)
#define KP_P (WS / 4.0f)

#define ISR_PER_MS (PWM_HZ / 1000)
#define ALIGN_DAMP (0.09f / KT)       /* 对零阻尼 A / (rad/s) */
#define FINDZ_RPM 120.0f             /* 开机找 Z 相的转速（示例；Z 相宽 4 个计数，16 kHz 采样看得到） */
#define UP_X100 7000                 /* 上针位 70°（第 138 轮） */

static float off_a = 2047.5f, off_b = 2047.5f, off_c = 2047.5f;
static uint32_t cal_n;
static float cal_a, cal_b, cal_c;
static float int_d, int_q, int_w;
/* 速度观测器（三阶：位置、转速、负载）：电机力矩 Kt·iq / J 作前馈，负载那一项由观测器自己估；极点都放在 ωo = 2π·100 Hz：
 * K1 = 3ωo、K2 = 3ωo²、K3 = ωo³。位置用浮点小数 + 整数基点，避免大计数时浮点精度不够 */
#define OBS_WO (TWO_PI * 100.0f)
#define OBS_K1 (3.0f * OBS_WO)
#define OBS_K2 (3.0f * OBS_WO * OBS_WO)
#define OBS_K3 (OBS_WO * OBS_WO * OBS_WO)
static int32_t obs_base;
static float obs_th, obs_w, obs_d;
static uint16_t cnt_prev16;
static uint32_t align_t, settle_ms, uv_ms;
static int z_prev = 1;
static int32_t stop_cnt;             /* 停针目标（展开的计数） */

/* ---------------------------------------------------------------- 数学（同 B 版：不用数学库） */
static float wrap_pi(float x)
{
    while (x > PI_F) {
        x -= TWO_PI;
    }
    while (x < -PI_F) {
        x += TWO_PI;
    }
    return x;
}

static void sincos(float x, float *s, float *c)
{
    x = wrap_pi(x);
    float sg = 1.0f;
    if (x > PI_F / 2) {
        x = PI_F - x;
        sg = -1.0f;
    } else if (x < -PI_F / 2) {
        x = -PI_F - x;
        sg = -1.0f;
    }
    float x2 = x * x;
    *s = x * (1.0f - x2 / 6.0f * (1.0f - x2 / 20.0f * (1.0f - x2 / 42.0f * (1.0f - x2 / 72.0f))));
    *c = sg * (1.0f - x2 / 2.0f * (1.0f - x2 / 12.0f * (1.0f - x2 / 30.0f * (1.0f - x2 / 56.0f * (1.0f - x2 / 90.0f)))));
}

static float clampf(float x, float lo, float hi) { return x < lo ? lo : (x > hi ? hi : x); }
static float absf(float x) { return x < 0 ? -x : x; }
static float sqrtf_(float x)
{
    if (x <= 0) {
        return 0;
    }
    float r = x > 1.0f ? x : 1.0f;
    for (int i = 0; i < 12; i++) {
        r = 0.5f * (r + x / r);
    }
    return r;
}

/* ---------------------------------------------------------------- 外设 */
void motor_init(void)
{
    mc.magic = 0x534C434Du;                                                       /* "MCLS" */
    RCC_APB2ENR |= RCC_TIM1EN | RCC_SYSCFGEN;
    RCC_APB1ENR1 |= RCC_TIM4EN;
    RCC_AHB2ENR |= RCC_ADC12EN | RCC_GPIOAEN | RCC_GPIOBEN | RCC_GPIOCEN;

    /* PB12 = IPM_SD：先输出低（功率模块关着），再设成输出 */
    GPIO_BSRR(GPIOB_BASE) = 1u << (12 + 16);
    GPIO_MODER(GPIOB_BASE) = (GPIO_MODER(GPIOB_BASE) & ~(3u << 24)) | (1u << 24);
    /* PA8–PA10、PB13–PB15 复用 AF6（TIM1） */
    GPIO_MODER(GPIOA_BASE) = (GPIO_MODER(GPIOA_BASE) & ~(0x3Fu << 16)) | (0x2Au << 16);
    GPIO_AFRH(GPIOA_BASE) = (GPIO_AFRH(GPIOA_BASE) & ~0xFFFu) | 0x666u;
    GPIO_MODER(GPIOB_BASE) = (GPIO_MODER(GPIOB_BASE) & ~(0x3Fu << 26)) | (0x2Au << 26);
    GPIO_AFRH(GPIOB_BASE) = (GPIO_AFRH(GPIOB_BASE) & ~(0xFFFu << 20)) | (0x666u << 20);
    /* PA0、PA1、PA7、PB0、PB1 模拟；PA6（Z 相）输入 */
    GPIO_MODER(GPIOA_BASE) |= (3u << 0) | (3u << 2) | (3u << 14);
    GPIO_MODER(GPIOA_BASE) &= ~(3u << 12);
    GPIO_MODER(GPIOB_BASE) |= (3u << 0) | (3u << 2);
    /* PB6 / PB7 复用 AF2（TIM4_CH1 / CH2） */
    GPIO_MODER(GPIOB_BASE) = (GPIO_MODER(GPIOB_BASE) & ~(0xFu << 12)) | (0xAu << 12);
    GPIO_AFRL(GPIOB_BASE) = (GPIO_AFRL(GPIOB_BASE) & ~(0xFFu << 24)) | (0x22u << 24);

    /* TIM4 编码器模式 3（A、B 两路边沿都计 = 4 倍频），输入滤波 N = 4，不分频，满量程 16 位 */
    TIM4_CCMR1 = 1u | (1u << 8) | (2u << 4) | (2u << 12);
    TIM4_CCER = 0;
    TIM4_SMCR = 3u;
    TIM4_ARR = 0xFFFFu;
    TIM4_CR1 = 1u;

    /* 片内运放 1–3：PGA 8 倍、同相输入 VINP0、输出接 ADC 内部通道、高速 */
    for (int n = 0; n < 3; n++) {
        OPAMP_CSR(n) = OPAMP_CSR_EN | OPAMP_CSR_VMSEL_PGA | OPAMP_CSR_HIGHSPEED | OPAMP_CSR_INTEN | OPAMP_CSR_GAIN8;
    }

    /* TIM1：中心对齐 1、16 kHz；PWM 模式 1 + 预装载；六路输出高有效（功率模块 HIN、LIN 高有效）；死区 1 µs；更新事件作 TRGO；RCR = 1 */
    TIM1_PSC = 0;
    TIM1_ARR = PWM_ARR;
    TIM1_RCR = 1;
    TIM1_CCMR1 = (6u << 4) | (1u << 3) | (6u << 12) | (1u << 11);
    TIM1_CCMR2 = (6u << 4) | (1u << 3);
    TIM1_CCER = (1u << 0) | (1u << 2) | (1u << 4) | (1u << 6) | (1u << 8) | (1u << 10);
    TIM1_CCR1 = TIM1_CCR2 = TIM1_CCR3 = PWM_ARR / 2;
    TIM1_BDTR = DTG_1US;                                                          /* MOE 先关 */
    TIM1_CR2 = 2u << 4;
    TIM1_EGR = 1u;

    /* ADC1、ADC2：时钟 HCLK/4、退出深度掉电、开稳压器、校准、使能；注入组由 TIM1_TRGO 上升沿触发 */
    ADC12_CCR = (ADC12_CCR & ~(3u << 16)) | (3u << 16);
    uint32_t adc[2] = {ADC1_BASE, ADC2_BASE};
    for (int k = 0; k < 2; k++) {
        ADC_CR(adc[k]) &= ~(1u << 29);
        ADC_CR(adc[k]) |= 1u << 28;
    }
    for (volatile int i = 0; i < 4000; i++) {                                     /* 稳压器启动 ≥ 20 µs */
    }
    for (int k = 0; k < 2; k++) {
        ADC_CR(adc[k]) |= 1u << 31;
        while (ADC_CR(adc[k]) & (1u << 31)) {
        }
        ADC_CR(adc[k]) |= 1u;
        while (!(ADC_ISR(adc[k]) & ADC_ISR_ADRDY)) {
        }
    }
    /* ADC1：3 路（U 相电流、母线、脚踏）；ADC2：2 路（V、W 相电流） */
    ADC_JSQR(ADC1_BASE) = 2u | (0u << 2) | (1u << 7) | (ADC_CH_VOPAMP1 << 9) | (ADC_CH_VBUS << 15) | (ADC_CH_PEDAL << 21);
    ADC_JSQR(ADC2_BASE) = 1u | (0u << 2) | (1u << 7) | (ADC_CH_VOPAMP2 << 9) | (ADC_CH_VOPAMP3 << 15);
    ADC_IER(ADC1_BASE) = 1u << 6;                                                 /* JEOSIE：ADC1 转完进中断（两个 ADC 同一个触发） */
    ADC_CR(ADC1_BASE) |= 1u << 3;
    ADC_CR(ADC2_BASE) |= 1u << 3;

    NVIC_IPR8(IRQ_ADC1_2) = 0x00;
    NVIC_ISER(IRQ_ADC1_2 / 32) = 1u << (IRQ_ADC1_2 % 32);
    TIM1_CR1 = (1u << 5) | (1u << 7) | 1u;                                        /* CMS = 01、ARPE、CEN */
}

static void outputs(int on)
{
    if (on) {
        int_d = int_q = int_w = 0;
        GPIO_BSRR(GPIOB_BASE) = 1u << 12;                                         /* IPM_SD 高：功率模块工作 */
        TIM1_BDTR |= TIM_BDTR_MOE;
    } else {
        TIM1_BDTR &= ~TIM_BDTR_MOE;
        GPIO_BSRR(GPIOB_BASE) = 1u << (12 + 16);
    }
    mc.moe = on ? 1u : 0u;
}

void motor_off(void)
{
    outputs(0);
    mc.mode = MM_OFF;
    mc.id_ref = mc.iq_ref = 0;
}

void motor_fault(uint32_t code, float val)
{
    motor_off();
    if (mc.state != MS_FAULT) {
        mc.fault = code;
        mc.fault_val = val;
    }
    mc.state = MS_FAULT;
}

void motor_start(void)
{
    align_t = 0;
    mc.state = MS_ALIGN;
    mc.mode = MM_OFF;
    outputs(1);
}

void motor_speed(float rpm)
{
    if (mc.mode != MM_SPEED) {
        if (mc.mode == MM_OFF) {
            int_w = 0;
            mc.speed_ref = mc.speed_rpm;
        }
        if (!mc.moe && mc.state != MS_FAULT) {
            outputs(1);
        }
        mc.mode = MM_SPEED;
    }
    mc.speed_tgt = clampf(rpm, 0, RPM_MAX);
}

static int32_t angle_of(int32_t cnt)
{
    int32_t a = (cnt - mc.z_cnt) % CNT_PER_REV;
    return a < 0 ? a + CNT_PER_REV : a;
}

void motor_stop_at(int32_t angle_x100)
{
    /* 目标：前面最近的这个转角（同 159c：刚过了不到 1° 就往回退，不再转一圈） */
    int32_t tgt = angle_x100 * (CNT_PER_REV / 2000) / 18;                       /* 0.01° → 计数（10000 / 36000 = 5 / 18） */
    int32_t ahead = (tgt - angle_of(mc.pos_cnt)) % CNT_PER_REV;
    if (ahead < 0) {
        ahead += CNT_PER_REV;
    }
    if (ahead > CNT_PER_REV - CNT_PER_REV / 360) {
        ahead -= CNT_PER_REV;
    }
    stop_cnt = mc.pos_cnt + ahead;
    mc.stop_x100 = angle_x100;
    settle_ms = 0;
    if (mc.mode != MM_POS && mc.mode != MM_SPEED) {
        int_w = 0;
        if (!mc.moe && mc.state != MS_FAULT) {
            outputs(1);
        }
    }
    mc.mode = MM_POS;
}

int motor_stopped(void) { return mc.mode == MM_POS && settle_ms >= 20u; }
int motor_ramp_done(void) { return mc.mode == MM_SPEED && mc.speed_ref == mc.speed_tgt; }

/* ---------------------------------------------------------------- 1 kHz：对零、找 Z 相、爬坡、位置环、保护 */
static void tick_ms(int32_t cnt)
{
    mc.ms++;
    /* 对零：d 轴通电至少 300 ms，并且转子停稳（转速 < 1 r/min 连续 50 ms）才记偏移，最多等 1 s。
     * 直驱主轴没有减速器，静止时几乎没有摩擦：只给 d 轴电流，转子会在零位两边摆很久（试跑：300 ms 时还在 ±200 r/min 摆，
     * 偏移记错约 45° 电角度，力矩只剩七成），所以对零时加阻尼（下面 iq = −转速 × 系数）、并等停稳。 */
    if (mc.state == MS_ALIGN) {
        align_t++;
        settle_ms = absf(mc.speed_rpm) < 1.0f ? settle_ms + 1u : 0u;
    }
    if (mc.state == MS_ALIGN && ((align_t >= 300u && settle_ms >= 50u) || align_t >= 1000u)) {
        int32_t o = cnt % CNT_PER_EREV;
        mc.align_off = o < 0 ? o + CNT_PER_EREV : o;
        mc.state = MS_FINDZ;
        settle_ms = 0;
        int_w = 0;
        mc.speed_ref = 0;
        mc.mode = MM_SPEED;
        mc.speed_tgt = FINDZ_RPM;
    }
    if (mc.state == MS_FINDZ && mc.z_seen && mc.mode == MM_SPEED) {
        motor_stop_at(UP_X100);
    }
    if (mc.state == MS_FINDZ && motor_stopped()) {
        mc.state = MS_READY;
    }

    /* 速度给定爬坡（加速、减速按 159c 的工作周期） */
    if (mc.mode == MM_SPEED) {
        float d = mc.speed_tgt - mc.speed_ref, up = ACC_UP * 0.001f, dn = ACC_DN * 0.001f;
        float step = d > 0 ? (d < up ? d : up) : (-d < dn ? d : -dn);
        mc.speed_ref += step;
        mc.acc_ref = step * 1000.0f / 60.0f * TWO_PI;
    } else {
        mc.acc_ref = 0;
    }
    /* 停针：位置环 P、限速 300 r/min */
    if (mc.mode == MM_POS) {
        int32_t ec = stop_cnt - cnt;
        float e = (float)(ec >= -1 && ec <= 1 ? 0 : ec) * (TWO_PI / CNT_PER_REV);   /* ±1 个计数（0.036°）以内不再修 */
        mc.pos_err_deg = (float)ec * (360.0f / CNT_PER_REV);
        mc.speed_ref = clampf(KP_P * e / TWO_PI * 60.0f, -STOP_RPM_MAX, STOP_RPM_MAX);
        if (absf(mc.pos_err_deg) <= 0.5f && absf(mc.speed_rpm) < 5.0f) {         /* 停稳：离目标 ≤ 0.5°、转速 < 5 r/min，连续 20 ms */
            settle_ms++;
        } else {
            settle_ms = 0;
        }
    }
    /* 保护：欠压（连续 5 ms）、堵转（电流顶到上限、转速 < 30 r/min，连续 200 ms；示例值） */
    if (mc.moe && mc.vbus < VBUS_MIN) {
        if (++uv_ms >= 5u) {
            motor_fault(MF_UV, mc.vbus);
        }
    } else {
        uv_ms = 0;
    }
    if (mc.moe && mc.mode == MM_SPEED && mc.speed_tgt > 0 && absf(mc.iq_ref) >= 0.95f * IQ_MAX && absf(mc.speed_rpm) < 30.0f) {
        if (++mc.stall_ms >= 200u) {
            motor_fault(MF_STALL, mc.iq_ref);
        }
    } else {
        mc.stall_ms = 0;
    }
    motor_ms_hook();
    mc.imax = 0;
}

/* ---------------------------------------------------------------- 16 kHz 电流环 */
void ADC1_2_IRQHandler(void)
{
    ADC_ISR(ADC1_BASE) = (1u << 5) | (1u << 6);                                   /* 清 JEOC、JEOS */
    ADC_ISR(ADC2_BASE) = (1u << 5) | (1u << 6);
    float ca = (float)ADC_JDR(ADC1_BASE, 0), cb = (float)ADC_JDR(ADC2_BASE, 0), cc = (float)ADC_JDR(ADC2_BASE, 1);
    mc.vbus = (float)ADC_JDR(ADC1_BASE, 1) * V_PER_CODE;
    mc.pedal_v = (float)ADC_JDR(ADC1_BASE, 2) * PEDAL_PER_CODE;
    mc.isr++;

    /* 开机前 64 个周期：输出关着，量电流零点 */
    if (cal_n < 64) {
        cal_a += ca; cal_b += cb; cal_c += cc;
        if (++cal_n == 64) {
            off_a = cal_a / 64; off_b = cal_b / 64; off_c = cal_c / 64;
        }
    }
    float ia = (off_a - ca) * A_PER_CODE, ib = (off_b - cb) * A_PER_CODE, ic = (off_c - cc) * A_PER_CODE;
    float am = absf(ia) > absf(ib) ? absf(ia) : absf(ib);
    am = am > absf(ic) ? am : absf(ic);
    if (am > mc.imax) {
        mc.imax = am;
    }
    if (am > I_TRIP && mc.moe) {                                                  /* 过流：本周期就关 */
        motor_fault(MF_OC, am);
    }

    /* 编码器：TIM4 的 16 位计数展开成 32 位 */
    uint16_t c16 = (uint16_t)TIM4_CNT;
    int32_t cnt = mc.pos_cnt + (int16_t)(uint16_t)(c16 - cnt_prev16);
    cnt_prev16 = c16;
    mc.pos_cnt = cnt;
    /* Z 相（PA6 低有效）：第一次见到下降沿记下计数 = 主轴 0°（针杆最高点） */
    int z = (int)((GPIO_IDR(GPIOA_BASE) >> 6) & 1u);
    if (!z && z_prev && !mc.z_seen && mc.state == MS_FINDZ) {
        mc.z_cnt = cnt;
        mc.z_seen = 1;
    }
    z_prev = z;
    if (mc.z_seen) {
        int32_t a_prev = mc.angle_x100;
        mc.angle_x100 = angle_of(cnt) * 18 / (CNT_PER_REV / 2000);                 /* 计数 → 0.01° */
        if (a_prev > 27000 && mc.angle_x100 < 9000) {                            /* 正转过 0°：一针 */
            motor_z_hook();
        }
    }
    /* 转速：观测器（见上）。B 版的“1 ms 差分 + 滤波”在 10000 计数/转时分辨率 6 r/min，停针保持时速度环把量化当真，
     * 主轴在目标附近来回抖（试跑看到 ±5 r/min）；只用二阶跟踪观测器、拿 Kt·iq / J 当前馈，有负载时估出的转速偏几百 r/min
     * （堵转时主轴不动、估出来还在转），所以用带负载估计的三阶观测器。 */
    {
        float e = (float)(cnt - obs_base) - obs_th;
        obs_th += (obs_w + OBS_K1 * e) * TS;
        if (obs_th > 1000.0f || obs_th < -1000.0f) {
            int32_t m = (int32_t)obs_th;
            obs_base += m;
            obs_th -= (float)m;
        }
        float a_iq = mc.moe ? mc.iq * (KT / J_TOTAL) * (CNT_PER_REV / TWO_PI) : 0.0f;
        obs_w += (a_iq - obs_d + OBS_K2 * e) * TS;
        obs_d += (-OBS_K3 * e) * TS;
        mc.speed_rpm = obs_w * (60.0f / CNT_PER_REV);
    }
    int32_t e = (cnt - mc.align_off) % CNT_PER_EREV;
    if (e < 0) {
        e += CNT_PER_EREV;
    }
    float th = (float)e * (TWO_PI / CNT_PER_EREV);
    if (mc.state == MS_ALIGN) {
        th = 0;                                                                   /* 对零：电流加在 d 轴 θe = 0 方向 */
    }
    float s, c;
    sincos(th, &s, &c);

    /* Clarke（幅值不变）、Park */
    float al = ia, be = (ia + 2.0f * ib) * 0.57735027f;
    mc.id = al * c + be * s;
    mc.iq = -al * s + be * c;

    /* 指令 */
    uint32_t k = mc.isr % ISR_PER_MS;
    if (mc.state == MS_ALIGN && mc.moe) {
        mc.id_ref = ALIGN_A;
        /* 阻尼：转子到零位附近时这一轴就是力矩轴；临界阻尼 c = 2√(K·J)，K = Kt·I·p ≈ 4 N·m/rad → c ≈ 0.09 N·m·s/rad */
        mc.iq_ref = clampf(-ALIGN_DAMP * mc.speed_rpm * (TWO_PI / 60.0f), -ALIGN_A, ALIGN_A);
    } else if (mc.moe && mc.mode != MM_OFF) {
        if (k % 8u == 0) {
            /* 2 kHz 速度环：PI + 加速度前馈 J·a / Kt（159c 同一做法） */
            float w = mc.speed_rpm / 60.0f * TWO_PI, wr = mc.speed_ref / 60.0f * TWO_PI;
            float ew = wr - w;
            float out = KP_W * ew + int_w + J_TOTAL * mc.acc_ref / KT;
            if (absf(out) < IQ_MAX) {
                int_w += KI_W * ew * 0.0005f;
            }
            mc.iq_ref = clampf(out, -IQ_MAX, IQ_MAX);
        }
        mc.id_ref = 0;
    } else {
        mc.id_ref = mc.iq_ref = 0;
    }

    /* d/q 电流 PI，电压限幅 Vbus/√3，抗积分饱和 */
    float vmax = mc.vbus * 0.57735027f;
    float ed = mc.id_ref - mc.id, eq = mc.iq_ref - mc.iq;
    float vd = KP_I * ed + int_d, vq = KP_I * eq + int_q;
    float mag = sqrtf_(vd * vd + vq * vq);
    if (mag < vmax) {
        int_d += KI_I * ed * TS;
        int_q += KI_I * eq * TS;
    } else if (mag > 0) {
        vd *= vmax / mag;
        vq *= vmax / mag;
    }
    mc.vd = vd;
    mc.vq = vq;

    /* 反 Park、反 Clarke、SVPWM（中点注入） */
    float va = vd * c - vq * s, vbt = vd * s + vq * c;
    float pa = va, pb = -0.5f * va + 0.8660254f * vbt, pc = -0.5f * va - 0.8660254f * vbt;
    /* 死区补偿：功率模块死区 1 µs × 16 kHz = 1.6 % 母线（390 V 时 6.2 V），按相电流方向补回去（电流小时线性过渡，±0.1 A）。
     * 不补的话低速保持时这几伏的误差让主轴在停针位附近慢慢来回晃（试跑看到 ±0.3°）。 */
    if (mc.moe) {
        float dv = mc.vbus * (1e-6f * PWM_HZ);
        pa += dv * clampf(ia * 10.0f, -1, 1);
        pb += dv * clampf(ib * 10.0f, -1, 1);
        pc += dv * clampf(ic * 10.0f, -1, 1);
    }
    float mx = pa > pb ? pa : pb, mn = pa < pb ? pa : pb;
    mx = mx > pc ? mx : pc;
    mn = mn < pc ? mn : pc;
    float z0 = -(mx + mn) * 0.5f, inv = mc.vbus > 1.0f ? 1.0f / mc.vbus : 0;
    TIM1_CCR1 = (uint32_t)(PWM_ARR * clampf(0.5f + (pa + z0) * inv, 0, 1));
    TIM1_CCR2 = (uint32_t)(PWM_ARR * clampf(0.5f + (pb + z0) * inv, 0, 1));
    TIM1_CCR3 = (uint32_t)(PWM_ARR * clampf(0.5f + (pc + z0) * inv, 0, 1));

    if (k == 0) {
        tick_ms(cnt);
    }
}

/* 系统时钟：HSI16 → PLL → 170 MHz（第 102 轮）。HSI16 / M=4 = 4 MHz，× N=85 = 340 MHz，/ R=2 = 170 MHz。
 * 170 MHz 要求：主调节器提升模式（PWR_CR5.R1MODE = 0）、Flash 4 个等待周期（RM0440 Flash 章“等待周期与电压”表）。 */
#include "clock.h"
#include "regs.h"

void clock_init(void)
{
    RCC_APB1ENR1 |= RCC_PWREN;
    PWR_CR5 &= ~(1u << 8);                            /* R1MODE = 0：提升模式 */
    FLASH_ACR = (FLASH_ACR & ~0xFu) | 4u | (1u << 8) | (1u << 9) | (1u << 10);   /* 4 等待周期、预取、指令 / 数据缓存 */
    RCC_PLLCFGR = 2u | (3u << 4) | (85u << 8) | (1u << 24);                    /* PLLSRC = HSI16、M = 4、N = 85、R = 2、PLLREN */
    RCC_CR |= 1u << 24;                               /* PLLON */
    while (!(RCC_CR & (1u << 25))) {                  /* 等 PLLRDY */
    }
    RCC_CFGR = (RCC_CFGR & ~3u) | 3u;                 /* SW = PLL */
    while (((RCC_CFGR >> 2) & 3u) != 3u) {            /* 等 SWS = PLL */
    }
}

/* 启动代码：向量表、复制 .data、清零 .bss、进 main（同驱动板 B 版；本板只用 ADC1_2 中断）。 */
#include <stdint.h>

extern uint32_t _estack, _sidata, _sdata, _edata, _sbss, _ebss;
int main(void);
void ADC1_2_IRQHandler(void);

void Reset_Handler(void)
{
    *(volatile uint32_t *)0xE000ED88u |= 0xFu << 20;   /* SCB_CPACR：先打开 FPU */
    __asm volatile("dsb\n isb");
    uint32_t *s = &_sidata, *d = &_sdata;
    while (d < &_edata) {
        *d++ = *s++;
    }
    for (d = &_sbss; d < &_ebss;) {
        *d++ = 0;
    }
    main();
    for (;;) {
    }
}

void Default_Handler(void)
{
    for (;;) {
    }
}

/* 向量表：16 个内核异常 + 外设中断（STM32G431：ADC1_2 = 18，其余不用） */
#define D Default_Handler
__attribute__((section(".isr_vector"), used)) const void *const vectors[16 + 19] = {
    &_estack, Reset_Handler, D, D, D, D, D, 0, 0, 0, 0, D, D, 0, D, D,   /* SP、复位、NMI、HardFault…SysTick */
    D, D, D, D, D, D, D, D, D, D, D, D, D, D, D, D, D, D,                /* 外设中断 0–17 */
    ADC1_2_IRQHandler,                                                   /* 18 */
};

/* STM32G431CB：128 KB Flash，SRAM1 + SRAM2 共 22 KB（RM0440 存储器映射） */
MEMORY
{
  FLASH (rx) : ORIGIN = 0x08000000, LENGTH = 128K
  RAM (rwx) : ORIGIN = 0x20000000, LENGTH = 22K
}
_estack = ORIGIN(RAM) + LENGTH(RAM);
SECTIONS
{
  .text : { KEEP(*(.isr_vector)) *(.text*) *(.rodata*) . = ALIGN(4); } > FLASH
  _sidata = LOADADDR(.data);
  .data : { _sdata = .; *(.data*) . = ALIGN(4); _edata = .; } > RAM AT > FLASH
  .bss (NOLOAD) : { _sbss = .; *(.bss*) *(COMMON) . = ALIGN(4); _ebss = .; } > RAM
}

// 平缝机控制器 CTRL-LS 的“功率级 + 被控对象”仿真外设（Renode，运行时编译）。第 159 轮 159f；写法照驱动板 B 版 WqDrive.cs（第 102 轮）。
//   WqSewMotor：TIM1 子集（三相中心对齐 PWM、MOE）+ 功率模块逆变平均模型（死区 1 µs，SD 脚 PB12 拉低关断）+ 三相永磁同步电机 d/q 模型
//               + 主轴负载：第 138 轮 G2 一转负载表（gen_load.py 生成，与 159c 的伺服复算同一张表、同一个算法）
//               + 编码器 Z 相（针杆最高点，主轴 0°；经 SN74LVC14 反相，低有效，宽 4 个计数）→ PA6
//               + 四个电磁铁（剪线 PA5、拨线 PA11、倒缝 PA12、抬压脚 PA15，引脚低 = 吸合）：记下每次吸合 / 释放的时刻和主轴转角；
//                 剪线电磁铁吸合、主轴在 200°–330° 时动刀切线，负载另加 0.15 N·m（与 gc_sim.py 相同，示例）
//               + 脚踏板霍尔电压（监视器命令 Pedal 给）；注入：针卡住（Jam，主轴瞬间卡死）、阻力太大（ExtraLoad，干摩擦）
//   WqTim4Enc ：TIM4 编码器模式子集（2500 线 ×4 = 10000 计数/转，16 位计数器）
//   WqAdc12   ：ADC1、ADC2 注入组子集（TIM1 更新时刻同时转换）：片内运放输出（三相电流，V = 1.65 − 0.1875 × i）、母线（22 k / 3.022 M）、脚踏（20 k / 30 k）
//   WqRcc     ：时钟就绪位（同 B 版）
// 寄存器偏移、位对照 ST 官方 CMSIS 头文件 stm32g431xx.h；运放接 ADC 的内部通道号对照 ST 官方 LL 驱动 stm32g4xx_ll_adc.h。
// 电机：力矩常数 0.496 N·m/A、惯量（转子 4×10⁻⁴ + 负载 1.24×10⁻⁴ kg·m²）取 159c；极对数、电阻、电感是示例值（第 138 轮电机未选型）。示例，不是某个型号。
using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using Antmicro.Renode.Core;
using Antmicro.Renode.Peripherals.Bus;
using Antmicro.Renode.Peripherals.Timers;
using Antmicro.Renode.Time;

namespace Antmicro.Renode.Peripherals.Miscellaneous
{
    public class WqSewMotor : IDoubleWordPeripheral, IKnownSize, IGPIOReceiver
    {
        // ---------------------------------------------------------------- 参数
        public const double Vbus0 = 390.0;           // 母线（159b 计算书：校正输出 390 V）
        public const double Kt = 0.496;              // N·m/A（159c）
        public const int P = 4;                      // 极对数（示例）
        public const double Psi = Kt / (1.5 * P);    // 永磁磁链 Wb：Kt = 1.5·p·ψ
        public const double Rs = 1.2;                // 相电阻 Ω（示例）
        public const double Ls = 0.004;              // 相电感 H（示例，Ld = Lq）
        public const double J = 4e-4 + 1.24e-4;      // 转子 + 机头负载 kg·m²（第 138 轮 G2、159c）
        public const double Dead = 1e-6;             // 死区 s（设计描述 ipm_inverter.t_dead）
        public const double Fpwm = 16000;            // 设计描述 ipm_inverter.f_pwm
        public const int Cpr = 10000;                // 2500 线 ×4
        public const double TrimT = 0.15, TrimOn = 200, TrimOff = 330;   // 剪线动刀（gc_sim.py，示例）

        public WqSewMotor(IMachine machine, IGPIOReceiver zPort = null)
        {
            this.machine = machine;
            this.zPort = zPort;
            pwm = new LimitTimer(machine.ClockSource, 170000000, this, "pwm", 5312, Direction.Ascending, false, WorkMode.Periodic, true);
            pwm.LimitReached += OnUpdate;
            Reset();
        }

        public long Size => 0x400;
        public WqAdc12 Adc { get; set; }

        // ---------------------------------------------------------------- 监视器命令
        public void LoadTable(string path)
        {
            var w = new List<double>(); var a = new List<double>(); var b = new List<double>();
            foreach(var ln in File.ReadAllLines(path))
            {
                if(ln.StartsWith("#") || ln.Trim() == "") continue;
                var f = ln.Split(' ');
                if(f[0] == "w5000") { w5 = double.Parse(f[1], CultureInfo.InvariantCulture); continue; }
                a.Add(double.Parse(f[1], CultureInfo.InvariantCulture));
                b.Add(double.Parse(f[2], CultureInfo.InvariantCulture));
            }
            tIn = a.ToArray(); tRs = b.ToArray();
        }
        public void StartAngle(double deg) { th = deg / 180 * Math.PI; }
        public void Pedal(double v) { Advance(); pedal = v; }
        public void Jam(bool v) { Advance(); jam = v; if(v) w = 0; }
        // 阻力太大（布太厚、线卡住）：另加一个干摩擦力矩 N·m，转着时阻碍转动，停着时电机力矩不超过它就转不动
        public void ExtraLoad(double nm) { Advance(); extra = nm; }
        public void SetVbus(double v) { Advance(); vbus = v; }
        public double PedalV => pedal;
        public double Vbus => vbus;

        public string Truth()
        {
            Advance();
            // 时刻 s、转速 r/min、主轴转角 °（0 = 针杆最高点）、id、iq、ia、ib、ic A、输出开着（MOE 且 SD 高）、母线 V、电机力矩 N·m、负载力矩 N·m、
            // 电磁铁（位 0 剪线、1 拨线、2 倒缝、3 抬压脚）、脚踏 V、累计转过的圈数
            return string.Format(CultureInfo.InvariantCulture, "M {0:F6} {1:F3} {2:F4} {3:F4} {4:F4} {5:F4} {6:F4} {7:F4} {8} {9:F2} {10:F4} {11:F4} {12} {13:F3} {14:F5}",
                Now(), w * 30 / Math.PI, Deg(), id, iq, Ia(), Ib(), Ic(), On() ? 1 : 0, vbus, 1.5 * P * Psi * iq, lastTl,
                SolBits(), pedal, th / (2 * Math.PI));
        }

        // 电磁铁动作记录：一行一次，“S 时刻 号 1/0 转角°”
        public string SolLog()
        {
            var s = new System.Text.StringBuilder();
            foreach(var e in log) s.AppendLine(e);
            return s.ToString();
        }

        public double EncoderCounts(double t) { return (th + w * Math.Max(0, t - tLast)) / (2 * Math.PI) * Cpr; }

        // ---------------------------------------------------------------- GPIO：0 剪线 PA5、1 拨线 PA11、2 倒缝 PA12、3 抬压脚 PA15、4 IPM_SD PB12
        public void OnGPIO(int number, bool value)
        {
            Advance();
            if(number == 4) { sd = value; return; }
            if(number < 0 || number > 3) return;
            // 复位时引脚是输入、外部上拉（电磁铁不动作）；GPIO 口模型复位时把连线置低，固件第一次把引脚置高以前的低电平不算吸合
            if(value) armed[number] = true;
            if(!armed[number]) return;
            bool on = !value;                                  // 引脚低 = 吸合
            if(sol[number] == on) return;
            sol[number] = on;
            log.Add(string.Format(CultureInfo.InvariantCulture, "S {0:F6} {1} {2} {3:F3}", Now(), number, on ? 1 : 0, Deg()));
        }

        // ---------------------------------------------------------------- 寄存器（偏移按 TIM_TypeDef）
        public uint ReadDoubleWord(long off)
        {
            switch(off)
            {
            case 0x00: return cr1;
            case 0x04: return cr2;
            case 0x18: return ccmr1;
            case 0x1C: return ccmr2;
            case 0x20: return ccer;
            case 0x28: return psc;
            case 0x2C: return arr;
            case 0x30: return rcr;
            case 0x34: return ccrP[0];
            case 0x38: return ccrP[1];
            case 0x3C: return ccrP[2];
            case 0x44: return bdtr;
            default: return 0;
            }
        }

        public void WriteDoubleWord(long off, uint v)
        {
            switch(off)
            {
            case 0x00: cr1 = v; Apply(); break;
            case 0x04: cr2 = v; break;
            case 0x14: if((v & 1) != 0) { LoadShadow(); } break;
            case 0x18: ccmr1 = v; break;
            case 0x1C: ccmr2 = v; break;
            case 0x20: ccer = v; break;
            case 0x28: psc = v & 0xFFFF; Apply(); break;
            case 0x2C: arr = v & 0xFFFF; Apply(); break;
            case 0x30: rcr = v & 0xFFFF; Apply(); break;
            case 0x34: ccrP[0] = v & 0xFFFF; break;
            case 0x38: ccrP[1] = v & 0xFFFF; break;
            case 0x3C: ccrP[2] = v & 0xFFFF; break;
            case 0x44: Advance(); bdtr = v; moe = (v & (1u << 15)) != 0; break;
            }
        }

        public void Reset()
        {
            cr1 = cr2 = ccmr1 = ccmr2 = ccer = psc = rcr = bdtr = 0;
            arr = 0xFFFF;
            ccrP = new uint[3]; ccrA = new uint[3];
            moe = false; sd = false; jam = false; extra = 0;
            sol = new bool[4]; armed = new bool[4]; log = new List<string>();
            id = iq = w = th = 0; vbus = Vbus0; pedal = 1.2; lastTl = 0;
            tLast = 0; zLevel = -1;
            pwm.Enabled = false;
        }

        private void Apply()
        {
            bool cen = (cr1 & 1) != 0;
            ulong lim = (ulong)arr * (psc + 1) * (rcr + 1);
            if(lim == 0) lim = 1;
            pwm.Limit = lim;
            if(cen && !pwm.Enabled) { tLast = Now(); }
            pwm.Enabled = cen;
        }

        private void LoadShadow() { for(int k = 0; k < 3; k++) ccrA[k] = ccrP[k]; }

        private void OnUpdate()
        {
            Advance();
            LoadShadow();
            if(Adc != null) Adc.Convert(Ia(), Ib(), Ic(), vbus, pedal);
        }

        // ---------------------------------------------------------------- 物理
        private double Now() { return machine.LocalTimeSource.ElapsedVirtualTime.TotalSeconds; }
        private bool On() { return moe && sd; }
        private double Deg() { var d = th % (2 * Math.PI); if(d < 0) d += 2 * Math.PI; return d * 180 / Math.PI; }
        private int SolBits() { int b = 0; for(int k = 0; k < 4; k++) if(sol[k]) b |= 1 << k; return b; }

        private void Advance()
        {
            double t = Now();
            double dt = t - tLast;
            if(dt > 0)
            {
                int n = Math.Max(1, (int)Math.Ceiling(dt / 2e-6));
                double h = dt / n;
                for(int k = 0; k < n; k++) Step(h);
                tLast = t;
            }
            // Z 相：主轴在 0°–0.144°（4 个计数）时引脚低
            double c = th / (2 * Math.PI) * Cpr % Cpr;
            if(c < 0) c += Cpr;
            int z = c < 4 ? 0 : 1;
            // 直接给 GPIOA 第 6 脚输入；每次都写（GPIO 口复位会清掉输入状态，只在变化时写会漏掉）
            if(zPort != null) { zLevel = z; zPort.OnGPIO(6, z == 1); }
        }

        private double Duty(int k) { return arr == 0 ? 0 : Math.Min(1.0, (double)ccrA[k] / arr); }

        private double Load(double ww)
        {
            if(tIn == null) return 0;
            double d = Deg();
            int i = (int)Math.Round(d / 0.5) % tIn.Length;
            double r = ww / w5;
            double t = tIn[i] * r * r + (ww > 1 ? tRs[i] : 0.0);
            if(sol[0] && d >= TrimOn && d <= TrimOff) t += TrimT;
            return t;
        }

        private void Step(double h)
        {
            double te = P * th;
            double c = Math.Cos(te), s = Math.Sin(te);
            double vd, vq;
            if(On())
            {
                double da = Duty(0), db = Duty(1), dc = Duty(2), m = (da + db + dc) / 3;
                double[] cur = { Ia(), Ib(), Ic() };
                double dv = vbus * Dead * Fpwm;
                double sm = (Math.Sign(cur[0]) + Math.Sign(cur[1]) + Math.Sign(cur[2])) / 3.0;
                double va = vbus * (da - m) - dv * (Math.Sign(cur[0]) - sm);
                double vb = vbus * (db - m) - dv * (Math.Sign(cur[1]) - sm);
                double vc = -va - vb;
                double al = va, be = (vb - vc) / Math.Sqrt(3);
                vd = al * c + be * s;
                vq = -al * s + be * c;
            }
            else
            {
                vd = -vbus * Math.Sign(id) * 0.5;               // 关断：续流回母线（同 B 版）
                vq = -vbus * Math.Sign(iq) * 0.5;
            }
            double we = P * w;
            double nid = id + (vd - Rs * id + we * Ls * iq) / Ls * h;
            double niq = iq + (vq - Rs * iq - we * Ls * id - we * Psi) / Ls * h;
            if(!On()) { if(Math.Sign(nid) != Math.Sign(id)) nid = 0; if(Math.Sign(niq) != Math.Sign(iq)) niq = 0; }
            id = nid; iq = niq;
            double tm = 1.5 * P * Psi * iq;
            double tl = Load(w);
            lastTl = tl;
            if(jam) { w = 0; return; }
            if(extra > 0)
            {
                if(Math.Abs(w) < 1e-3 && Math.Abs(tm - tl) <= extra) { w = 0; return; }   // 卡着不动
                double w2 = w + (tm - tl - extra * Math.Sign(w == 0 ? tm - tl : w)) / J * h;
                if(w != 0 && Math.Sign(w2) != Math.Sign(w)) { w = 0; return; }
                w = w2;
                th += w * h;
                return;
            }
            w += (tm - tl) / J * h;
            th += w * h;
        }

        private double Ia() { var te = P * th; return id * Math.Cos(te) - iq * Math.Sin(te); }
        private double Ib() { var te = P * th - 2 * Math.PI / 3; return id * Math.Cos(te) - iq * Math.Sin(te); }
        private double Ic() { var te = P * th + 2 * Math.PI / 3; return id * Math.Cos(te) - iq * Math.Sin(te); }

        private readonly IMachine machine;
        private readonly LimitTimer pwm;
        private uint cr1, cr2, ccmr1, ccmr2, ccer, psc, arr, rcr, bdtr;
        private uint[] ccrP, ccrA;
        private bool moe, sd, jam;
        private bool[] sol, armed;
        private List<string> log;
        private double id, iq, w, th, vbus, tLast, pedal, lastTl, extra, w5 = 523.598776;
        private double[] tIn, tRs;
        private int zLevel;
        private readonly IGPIOReceiver zPort;
    }

    // ==================================================================== TIM4 编码器模式
    // 只做编码器模式 3（SMCR.SMS = 0011，A、B 两路边沿都计）：CNT = 开计数器以来电机转过的计数（16 位回绕）。其余模式读 0。
    public class WqTim4Enc : IDoubleWordPeripheral, IKnownSize
    {
        public WqTim4Enc(IMachine machine, WqSewMotor motor) { this.machine = machine; this.motor = motor; Reset(); }
        public long Size => 0x400;

        public uint ReadDoubleWord(long off)
        {
            switch(off)
            {
            case 0x00: return cr1;
            case 0x08: return smcr;
            case 0x18: return ccmr1;
            case 0x20: return ccer;
            case 0x24: return Cnt();
            case 0x2C: return arr;
            default: return 0;
            }
        }

        public void WriteDoubleWord(long off, uint v)
        {
            switch(off)
            {
            case 0x00:
                if((v & 1) != 0 && (cr1 & 1) == 0) base0 = Math.Floor(motor.EncoderCounts(T()));
                cr1 = v; break;
            case 0x08: smcr = v; break;
            case 0x18: ccmr1 = v; break;
            case 0x20: ccer = v; break;
            case 0x2C: arr = v & 0xFFFF; break;
            }
        }

        public void Reset() { cr1 = smcr = ccmr1 = ccer = 0; arr = 0xFFFF; base0 = 0; }

        private uint Cnt()
        {
            uint sms = (smcr & 7) | (((smcr >> 16) & 1) << 3);
            if((cr1 & 1) == 0 || sms != 3) return 0;
            double c = Math.Floor(motor.EncoderCounts(T())) - base0;
            long n = (long)c % ((long)arr + 1);
            if(n < 0) n += (long)arr + 1;
            return (uint)n;
        }

        private double T() { return machine.LocalTimeSource.ElapsedVirtualTime.TotalSeconds; }
        private readonly IMachine machine;
        private readonly WqSewMotor motor;
        private uint cr1, smcr, ccmr1, ccer, arr;
        private double base0;
    }

    // ==================================================================== ADC1 + ADC2 注入组（0x5000 0000，ADC2 在 +0x100，公共寄存器 +0x300）
    public class WqAdc12 : IDoubleWordPeripheral, IKnownSize
    {
        public WqAdc12(IMachine machine, WqSewMotor motor) { this.motor = motor; motor.Adc = this; Reset(); }
        public long Size => 0x400;
        public GPIO IRQ { get; } = new GPIO();      // ADC1_2（中断 18）

        public void Convert(double ia, double ib, double ic, double vbus, double pedal)
        {
            for(int k = 0; k < 2; k++)
            {
                if((cr[k] & 1) == 0 || (cr[k] & (1u << 3)) == 0 || ((jsqr[k] >> 7) & 3) == 0) continue;   // ADEN、JADSTART、JEXTEN
                int n = (int)(jsqr[k] & 3) + 1;
                for(int j = 0; j < n; j++)
                {
                    uint ch = (jsqr[k] >> (9 + 6 * j)) & 0x1F;
                    double v = 0;
                    if(k == 0 && ch == 13) v = 1.65 - 0.1875 * ia;          // OPAMP1：U 相
                    else if(k == 0 && ch == 1) v = vbus * 22.0 / 3022.0;     // PA0：母线
                    else if(k == 0 && ch == 12) v = pedal * 20.0 / 30.0;     // PB1：脚踏
                    else if(k == 1 && ch == 16) v = 1.65 - 0.1875 * ib;      // OPAMP2：V 相
                    else if(k == 1 && ch == 18) v = 1.65 - 0.1875 * ic;      // OPAMP3：W 相
                    jdr[k, j] = Code(v);
                }
                isr[k] |= (1u << 5) | (1u << 6);
            }
            Update();
        }

        public uint ReadDoubleWord(long off)
        {
            int k = (int)(off >> 8);
            long o = off & 0xFF;
            if(k > 1) return k == 3 && o == 0x08 ? ccr : 0;
            switch(o)
            {
            case 0x00: return isr[k];
            case 0x04: return ier[k];
            case 0x08: return cr[k];
            case 0x4C: return jsqr[k];
            case 0x80: return jdr[k, 0];
            case 0x84: return jdr[k, 1];
            case 0x88: return jdr[k, 2];
            case 0x8C: return jdr[k, 3];
            default: return 0;
            }
        }

        public void WriteDoubleWord(long off, uint v)
        {
            int k = (int)(off >> 8);
            long o = off & 0xFF;
            if(k > 1) { if(k == 3 && o == 0x08) ccr = v; return; }
            switch(o)
            {
            case 0x00: isr[k] &= ~v; Update(); break;
            case 0x04: ier[k] = v; Update(); break;
            case 0x08:
                cr[k] = v & ~(1u << 31);                    // ADCAL 立即完成
                if((v & 1) != 0) isr[k] |= 1;               // ADRDY
                break;
            case 0x4C: jsqr[k] = v; break;
            }
        }

        public void Reset() { isr = new uint[2]; ier = new uint[2]; cr = new uint[2]; jsqr = new uint[2]; jdr = new uint[2, 4]; ccr = 0; IRQ.Unset(); }

        private void Update() { IRQ.Set((((isr[0] & ier[0]) | (isr[1] & ier[1])) & (1u << 6)) != 0); }   // JEOS 中断（两个 ADC 共用中断 18）
        private static uint Code(double v) { return (uint)Math.Max(0, Math.Min(4095, Math.Round(v / 3.3 * 4095))); }

        private readonly WqSewMotor motor;
        private uint[] isr, ier, cr, jsqr;
        private uint[,] jdr;
        private uint ccr;
    }

    // ==================================================================== RCC：固件等待的就绪位（同 B 版）
    public class WqRcc : IDoubleWordPeripheral, IKnownSize
    {
        public WqRcc() { Reset(); }
        public long Size => 0x400;

        public uint ReadDoubleWord(long off)
        {
            uint v;
            mem.TryGetValue(off, out v);
            if(off == 0x00)
            {
                if((v & (1u << 8)) != 0) v |= 1u << 10;       // HSION → HSIRDY
                if((v & (1u << 24)) != 0) v |= 1u << 25;      // PLLON → PLLRDY
            }
            if(off == 0x08) v = (v & ~0xCu) | ((v & 3) << 2);  // SWS 跟随 SW
            return v;
        }

        public void WriteDoubleWord(long off, uint v) { mem[off] = v; }
        public void Reset() { mem = new Dictionary<long, uint> { { 0x00, 1u << 8 }, { 0x08, 1 } }; }

        private Dictionary<long, uint> mem;
    }
}
